try {
  const vendorCategories = {};

  for (const item of items) {
    const d = item.json;
    if (d.error) continue;
    for (const supplier of Object.keys(d.suppliers || {})) {
      if (!vendorCategories[supplier]) vendorCategories[supplier] = new Set();
      vendorCategories[supplier].add(d.category);
    }
  }

  return items.map((item) => {
    const data = item.json;
    if (data.error) return { json: data };

    const totalSpend = data.totalSpend;
    const supplierNames = Object.keys(data.suppliers || {});
    const supplierCount = supplierNames.length;
    const shares = supplierNames.map((s) => data.supplierShares[s] || 0);
    const hhi = shares.reduce((sum, s) => sum + s * s, 0);
    const dominance = shares.length > 0 ? Math.max(...shares) : 0;
    const fragmentation_index = Number(Math.min(1, (1 - hhi) * (supplierCount / 5)).toFixed(2));

    let cross_category_overlap = false;
    let overlap_vendor = '';
    for (const s of supplierNames) {
      const cats = vendorCategories[s];
      if (cats && cats.size >= 3) {
        cross_category_overlap = true;
        overlap_vendor = s;
        break;
      }
    }

    const tailSuppliers = supplierNames.filter((s) => {
      const share = data.supplierShares[s] || 0;
      const txns = data.supplierTxns[s] || 0;
      return share < 0.1 && txns < 3;
    });

    const sorted = [...supplierNames].sort((a, b) => data.suppliers[b] - data.suppliers[a]);
    const primarySupplier = sorted[0] || '';
    const suppliers_to_merge = tailSuppliers.filter((s) => s !== primarySupplier);

    let strategy_type = 'optimized';
    let target_supplier_count = supplierCount;
    let consolidation_play = 'Category is well optimized — monitor only';

    if (cross_category_overlap) {
      strategy_type = 'msa';
      target_supplier_count = 1;
      consolidation_play = `Negotiate cross-category MSA with ${overlap_vendor} across ${vendorCategories[overlap_vendor].size} categories`;
    } else if (supplierCount === 1 && dominance > 0.7) {
      strategy_type = 'diversify';
      target_supplier_count = 2;
      consolidation_play = `Add backup supplier to reduce dependency on ${primarySupplier} (${Math.round(dominance * 100)}% dominance)`;
    } else if (tailSuppliers.length >= 2 || supplierCount >= 3) {
      strategy_type = 'consolidation';
      target_supplier_count = Math.min(2, supplierCount);
      const mergeNames = suppliers_to_merge.slice(0, Math.max(1, supplierCount - target_supplier_count));
      if (mergeNames.length > 0) {
        consolidation_play = `Merge ${mergeNames.length} supplier${mergeNames.length > 1 ? 's' : ''} (${mergeNames.join(', ')}) → retain ${primarySupplier} + ${Math.max(0, target_supplier_count - 1)} backup`;
      } else {
        consolidation_play = `Reduce from ${supplierCount} to ${target_supplier_count} suppliers — focus on ${primarySupplier}`;
      }
    } else if (supplierCount === 2) {
      strategy_type = 'consolidation';
      target_supplier_count = 1;
      consolidation_play = `Consolidate ${sorted[1]} into ${primarySupplier} for volume leverage`;
    }

    const tail_spend = tailSuppliers.reduce((sum, s) => sum + data.suppliers[s], 0);
    let savingsPct = Math.min(12, 2 * Math.max(0, supplierCount - target_supplier_count));
    let savingsAmount = tail_spend * 0.15 + (totalSpend * savingsPct) / 100;
    if (cross_category_overlap) savingsPct = Math.min(12, savingsPct + 3);
    if (dominance > 0.7) {
      savingsAmount *= 0.5;
      savingsPct *= 0.5;
    }
    savingsAmount = Math.round(savingsAmount);
    savingsPct = Number(savingsPct.toFixed(2));

    const riskScore = supplierCount >= 4 ? 9 : supplierCount === 3 ? 7 : supplierCount === 2 ? 5 : 2;
    const optimizationLevel = strategy_type === 'optimized' ? 'Optimized' : savingsPct >= 10 ? 'High Opportunity' : 'Moderate Opportunity';

    return {
      json: {
        ...data,
        hhi: Number(hhi.toFixed(4)),
        dominance: Number(dominance.toFixed(2)),
        fragmentation_index,
        cross_category_overlap,
        overlap_vendor,
        tailSuppliers,
        suppliers_to_merge,
        primarySupplier,
        current_supplier_count: supplierCount,
        target_supplier_count,
        strategy_type,
        consolidation_play,
        estimated_savings_amount: savingsAmount,
        estimated_savings_pct: savingsPct,
        estimatedSavings: savingsAmount,
        savingsPercentage: savingsPct,
        riskScore,
        optimizationLevel,
      },
    };
  });
} catch (error) {
  return [{ json: { error: true, stage: 'Fragmentation & Scenarios', message: error.message } }];
}

const staticData = $getWorkflowStaticData('global');
if (!staticData.lastRun) staticData.lastRun = {};

const validItems = items.filter((i) => !i.json.error);
const maxSpend = Math.max(...validItems.map((i) => i.json.totalSpend || 0), 1);

return items.map((item) => {
  const d = item.json;
  if (d.error) return { json: d };

  const prev = staticData.lastRun[d.category];
  let trend_delta = 'new';
  if (prev) {
    const fragDelta = d.fragmentation_index - (prev.fragmentation_index || 0);
    if (fragDelta > 0.05) trend_delta = 'worsening';
    else if (fragDelta < -0.05) trend_delta = 'improving';
    else trend_delta = 'stable';
  }

  const spendWeight = (d.totalSpend / maxSpend) * 40;
  const fragWeight = d.fragmentation_index * 30;
  const savingsWeight = (d.estimated_savings_pct / 12) * 20;
  const trendBonus = trend_delta === 'worsening' ? 15 : trend_delta === 'new' ? 5 : 0;
  const priority_score = Math.round(Math.min(100, spendWeight + fragWeight + savingsWeight + trendBonus));
  const priority_level = priority_score >= 75 ? 'Critical' : priority_score >= 60 ? 'High' : priority_score >= 40 ? 'Medium' : 'Low';
  const high_priority = priority_score >= 60 || d.estimated_savings_amount >= 5000 || d.fragmentation_index >= 0.6 || trend_delta === 'worsening';

  return {
    json: {
      ...d,
      trend_delta,
      priority_score,
      priority_level,
      high_priority,
    },
  };
});

