try {
  const lookbackDays = 30;
  const cutoff = new Date();
  cutoff.setDate(cutoff.getDate() - lookbackDays);
  cutoff.setHours(0, 0, 0, 0);

  const grouped = {};

  for (const item of items) {
    const row = item.json;
    if (!row.created_at || !row.category || !row.supplier || row.amount === undefined) continue;

    const rowDate = new Date(String(row.created_at).split('T')[0]);
    if (isNaN(rowDate.getTime()) || rowDate < cutoff) continue;

    const category = String(row.category).trim();
    const supplier = String(row.supplier).trim();
    const amount = Number(row.amount);
    if (isNaN(amount)) continue;

    if (!grouped[category]) {
      grouped[category] = {
        totalSpend: 0,
        suppliers: {},
        supplierTxns: {},
        departments: {},
        txnCount: 0,
      };
    }

    grouped[category].totalSpend += amount;
    grouped[category].txnCount += 1;
    grouped[category].suppliers[supplier] = (grouped[category].suppliers[supplier] || 0) + amount;
    grouped[category].supplierTxns[supplier] = (grouped[category].supplierTxns[supplier] || 0) + 1;

    if (row.department) {
      const dept = String(row.department).trim();
      grouped[category].departments[dept] = (grouped[category].departments[dept] || 0) + amount;
    }
  }

  const results = Object.keys(grouped).map((category) => {
    const g = grouped[category];
    const supplierNames = Object.keys(g.suppliers);
    const supplierCount = supplierNames.length;
    const supplierShares = {};
    let tailSpend = 0;

    for (const s of supplierNames) {
      const share = g.totalSpend > 0 ? g.suppliers[s] / g.totalSpend : 0;
      supplierShares[s] = Number(share.toFixed(4));
      const txns = g.supplierTxns[s] || 0;
      if (share < 0.1 && txns < 3) tailSpend += g.suppliers[s];
    }

    return {
      json: {
        category,
        totalSpend: Math.round(g.totalSpend),
        suppliers: g.suppliers,
        supplierTxns: g.supplierTxns,
        supplierCount,
        supplierShares,
        txnCount: g.txnCount,
        avgOrderValue: g.txnCount > 0 ? Math.round(g.totalSpend / g.txnCount) : 0,
        tailSpendPct: g.totalSpend > 0 ? Number(((tailSpend / g.totalSpend) * 100).toFixed(2)) : 0,
        departments: g.departments,
      },
    };
  });

  if (results.length === 0) {
    return [{ json: { error: true, stage: 'Validate & Build Matrix', message: 'No valid transactions in 30-day window' } }];
  }

  return results;
} catch (error) {
  return [{ json: { error: true, stage: 'Validate & Build Matrix', message: error.message } }];
}

const rankedAll = $('Compare, Score & Rank').all();

return $input.all().map((item, index) => {
  const base = rankedAll[index]?.json || {};
  const rawOutput = item.json.output;

  let pass1 = {};
  try {
    pass1 = typeof rawOutput === 'string'
      ? JSON.parse(rawOutput)
      : (rawOutput || {});
  } catch (error) {
    pass1 = {
      parse_error: true,
      error: error.message,
      raw_output: rawOutput,
    };
  }

  return {
    json: {
      // Keep all analytics fields from Compare, Score & Rank
      ...base,

      // Parsed AI Pass 1 object
      pass1,

      // Flat fields for easier prompt usage
      pass1_anomalies: pass1.anomalies || [],
      pass1_leakage_flags: pass1.leakage_flags || [],
      pass1_vendor_duplicates: pass1.vendor_duplicates || [],
      pass1_spend_pattern_summary: pass1.spend_pattern_summary || '',
      pass1_risk_signals: pass1.risk_signals || [],
      pass1_parse_error: pass1.parse_error || false,
    },
  };
});

function parseAI(raw) {
  try {
    if (!raw) return null;
    if (typeof raw === 'object') return raw;
    const text = String(raw).trim();
    const cleaned = text.replace(/^```json\s*/i, '').replace(/```\s*$/i, '').trim();
    return JSON.parse(cleaned);
  } catch (e) {
    return null;
  }
}

function ruleBasedFallback(d) {
  return {
    kraljic_quadrant: d.totalSpend > 500000 ? 'Strategic' : d.riskScore >= 7 ? 'Leverage' : 'Routine',
    consolidation_play: d.consolidation_play,
    recommendation: d.consolidation_play,
    implementation_steps: [
      `Week 1-4: Evaluate ${(d.suppliers_to_merge || []).length} tail suppliers for consolidation`,
      `Week 5-8: Negotiate volume pricing with ${d.primarySupplier || 'primary supplier'}`,
      `Week 9-12: Execute ${d.strategy_type} strategy — target ${d.target_supplier_count} supplier(s)`,
    ],
    negotiation_levers: ['Volume consolidation discount', 'Extended payment terms'],
    risks: d.dominance > 0.7 ? ['High supplier dependency'] : ['Change management during transition'],
    search_queries: [],
    issue: d.strategy_type === 'optimized' ? 'No major fragmentation detected' : `Fragmented spend across ${d.current_supplier_count} suppliers`,
    insight: `Estimated ${d.estimated_savings_pct}% savings (₹${d.estimated_savings_amount}) via ${d.strategy_type} strategy`,
    ai_pass2_used: false,
  };
}

const rankedAll = $('Compare, Score & Rank').all();
const pass1All = $('AI Pass 1: Spend Pattern Analyst').all();

let pass2All = [];
try {
  pass2All = $('AI Pass 2: Playbook Strategist').all();
} catch (e) {
  pass2All = [];
}

const highCount = rankedAll.filter((r) => r.json.high_priority).length;
const inputCount = $input.all().length;

// Wait for Pass 2 if needed
if (highCount > 0 && pass2All.length < highCount) {
  return [];
}

// Prevent false-branch duplicate output
if (highCount > 0 && pass2All.length >= highCount && inputCount !== pass2All.length) {
  return [];
}

const pass2ByCategory = {};
for (let i = 0; i < pass2All.length; i++) {
  const ranked = rankedAll.filter((r) => r.json.high_priority)[i];
  if (!ranked) continue;
  const parsed = parseAI(pass2All[i].json.output);
  if (parsed) pass2ByCategory[ranked.json.category] = parsed;
}

const enriched = rankedAll.map((rankItem, idx) => {
  const base = rankItem.json;
  const pass1 = parseAI(pass1All[idx]?.json?.output) || {
    anomalies: [],
    leakage_flags: [],
    vendor_duplicates: [],
    spend_pattern_summary: '',
    risk_signals: [],
  };

  let pass2 = base.high_priority ? pass2ByCategory[base.category] : null;
  if (!pass2 || !(pass2.implementation_steps || pass2.kraljic_quadrant)) {
    pass2 = ruleBasedFallback(base);
  } else {
    pass2.ai_pass2_used = true;
  }

  return {
    json: {
      ...base,
      anomalies: pass1.anomalies || [],
      leakage_flags: pass1.leakage_flags || [],
      vendor_duplicates: pass1.vendor_duplicates || [],
      spend_pattern_summary: pass1.spend_pattern_summary || '',
      risk_signals: pass1.risk_signals || [],
      kraljic_quadrant: pass2.kraljic_quadrant || 'Unclassified',
      consolidation_play: pass2.consolidation_play || base.consolidation_play,
      recommendation: pass2.recommendation || base.consolidation_play,
      implementation_steps: pass2.implementation_steps || [],
      negotiation_levers: pass2.negotiation_levers || [],
      risks: pass2.risks || [],
      search_queries: pass2.search_queries || [],
      issue: pass2.issue || '',
      insight: pass2.insight || pass1.spend_pattern_summary || '',
      ai_pass2_used: pass2.ai_pass2_used || false,
    },
  };
});

const valid = enriched.filter((e) => !e.json.error);
const totalSavings = valid.reduce((s, e) => s + (e.json.estimated_savings_amount || 0), 0);
const totalSpend = valid.reduce((s, e) => s + (e.json.totalSpend || 0), 0);
const worseningCount = valid.filter((e) => e.json.trend_delta === 'worsening').length;
const avgFrag = valid.length ? valid.reduce((s, e) => s + (e.json.fragmentation_index || 0), 0) / valid.length : 0;
const portfolio_health_score = Math.round(Math.max(0, 100 - avgFrag * 60 - worseningCount * 5));

const top_plays = [...valid]
  .sort((a, b) => (b.json.priority_score || 0) - (a.json.priority_score || 0))
  .slice(0, 5)
  .map((e) => ({
    category: e.json.category,
    consolidation_play: e.json.consolidation_play,
    estimated_savings_amount: e.json.estimated_savings_amount,
    priority_score: e.json.priority_score,
  }));

const portfolio = {
  portfolio_total_savings: totalSavings,
  portfolio_total_spend: totalSpend,
  portfolio_health_score,
  worsening_count: worseningCount,
  category_count: valid.length,
  top_plays,
  dashboardLink: 'https://datastudio.google.com/reporting/710755a7-d97c-468c-9052-502525f25c9e',
};

const staticData = $getWorkflowStaticData('global');
if (!staticData.lastRun) staticData.lastRun = {};
for (const e of valid) {
  staticData.lastRun[e.json.category] = {
    fragmentation_index: e.json.fragmentation_index,
    supplierCount: e.json.supplierCount,
    totalSpend: e.json.totalSpend,
    estimated_savings_amount: e.json.estimated_savings_amount,
    updatedAt: new Date().toISOString(),
  };
}

return enriched.map((e) => ({ json: { ...e.json, ...portfolio } }));
